#include "AutoEq.h"
#include <cmath>
#include <algorithm>
#include <random>
#include <iostream>
#include <stdexcept>
namespace {void check(bool v,const char* s){if(!v)throw std::runtime_error(s);}vocal::AudioChannels voice(float bass=0,float harsh=0,float gain=1){vocal::AudioChannels a(1,std::vector<float>(48000*8));vocal::Biquad low,high;low.configure(vocal::Biquad::lowShelf,48000,240,.707,bass);high.configure(vocal::Biquad::peak,48000,3200,.8,harsh);double phase=0;for(std::size_t i=0;i<a[0].size();++i){const double t=i/48000.0,hz=150*std::pow(2,(static_cast<int>(t)%4)*2/12.0);phase+=2*vocal::pi*hz/48000;float v=0;for(int h=1;h<=30;++h)v+=static_cast<float>(.07/std::pow(h,1.1)*std::sin(h*phase));a[0][i]=gain*high.tick(low.tick(v));}return a;}}
int main(){try{std::atomic<bool> cancel{false};std::atomic<float> progress{0};vocal::EqSettings before;auto source=voice();const auto original=source;auto normal=vocal::recommendEq(source,48000,before,cancel,progress);check(normal.valid&&normal.voicedSeconds>=3,"clear sung voice accepted");check(source==original,"analysis must preserve raw audio");auto boomy=vocal::recommendEq(voice(9),48000,before,cancel,progress),bright=vocal::recommendEq(voice(0,12),48000,before,cancel,progress),quiet=vocal::recommendEq(voice(0,0,.3f),48000,before,cancel,progress);std::cout<<"neutral warmth="<<normal.suggested.warmth<<" boomy="<<boomy.suggested.warmth<<" neutral presence="<<normal.suggested.presence<<" bright="<<bright.suggested.presence<<"\n";check(boomy.valid&&bright.valid&&quiet.valid,"colored and quiet vocal accepted");check(boomy.suggested.warmth<normal.suggested.warmth,"boomy recording receives more low-shelf reduction");check(bright.suggested.presence<normal.suggested.presence,"harsh recording receives more presence reduction");check(std::abs(quiet.suggested.warmth-normal.suggested.warmth)<.05&&std::abs(quiet.suggested.presence-normal.suggested.presence)<.05,"recommendation must not confuse lower recording level with different tone");for(const auto* r:{&normal,&boomy,&bright}){check(r->suggested.valid()&&r->suggested.highPass<=90&&r->suggested.warmth>=-3&&r->suggested.warmth<=1&&r->suggested.presence>=-3&&r->suggested.presence<=1.5,"conservative EQ limits");check(std::abs(r->matchDb)<=3,"bounded A/B level compensation");}
    vocal::AudioChannels silence(1,std::vector<float>(48000*6));check(!vocal::recommendEq(silence,48000,before,cancel,progress).valid,"silence rejected");std::mt19937 random(8);std::uniform_real_distribution<float> noise(-.05,.05);for(float& v:silence[0])v=noise(random);check(!vocal::recommendEq(silence,48000,before,cancel,progress).valid,"unvoiced noise rejected");auto clipped=voice();for(auto& v:clipped[0])v=std::clamp(v*30,-1.0f,1.0f);check(!vocal::recommendEq(clipped,48000,before,cancel,progress).valid,"severe clipping rejects automatic EQ");cancel=true;check(!vocal::recommendEq(source,48000,before,cancel,progress).valid,"cancellation leaves no valid suggestion");std::cout<<"PASS: dry voice, coloration, gain invariance, conservative limits, silence/noise/clip guard and cancel\n";return 0;}catch(const std::exception& e){std::cerr<<"FAIL: "<<e.what()<<"\n";return 1;}}
